def mcp_call(method, params, cid=2):
    """Call the world MCP server (automationbench) over HTTP and return the raw JSON-RPC response."""
    import json, urllib.request
    BASE = "http://127.0.0.1:40573/mcp/7ef7404321f2a52c49c52db3bc5f61a2"
    def post(payload):
        req = urllib.request.Request(
            BASE,
            data=json.dumps(payload).encode(),
            headers={"Content-Type": "application/json", "Accept": "application/json, text/event-stream"},
            method="POST",
        )
        with urllib.request.urlopen(req, timeout=30) as resp:
            return resp.read().decode()
    post({"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2024-11-05","capabilities":{},"clientInfo":{"name":"chaos","version":"0"}}})
    return post({"jsonrpc":"2.0","id":cid,"method":method,"params":params})

def _text(raw):
    import json
    try:
        data = json.loads(raw)
        r = data.get("result", {})
        if "content" in r:
            return "\n".join(c.get("text","") for c in r["content"])
        return json.dumps(r)[:4000]
    except Exception:
        return raw[:4000]

def mcp_search(query):
    """Search the world API: tools/call mcp__world__api_search with query."""
    return _text(mcp_call("tools/call", {"name":"mcp__world__api_search","arguments":{"query":query}}, cid=3))

def mcp_fetch(url):
    """Fetch a world API resource: tools/call mcp__world__api_fetch with url."""
    return _text(mcp_call("tools/call", {"name":"mcp__world__api_fetch","arguments":{"url":url}}, cid=4))

